#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    char out[1024];
    size_t out_len = 0;
    if (strcmp(mode, "to_camel") == 0) {
        int capitalize = 0;
        for (size_t i = 0; input[i] && out_len < sizeof(out) - 1; i++) {
            char c = input[i];
            if (c == '_') {
                capitalize = 1;
                continue;
            }
            if (capitalize && c >= 'a' && c <= 'z') {
                c = c - ('a' - 'A');
            }
            capitalize = 0;
            out[out_len++] = c;
        }
        out[out_len] = '\0';
        puts(out);
    } else if (strcmp(mode, "to_snake") == 0) {
        for (size_t i = 0; input[i] && out_len < sizeof(out) - 1; i++) {
            char c = input[i];
            if (c >= 'A' && c <= 'Z') {
                if (i != 0) {
                    out[out_len++] = '_';
                }
                c = c + ('a' - 'A');
            }
            out[out_len++] = c;
        }
        out[out_len] = '\0';
        puts(out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
